class RCIResponseQueue(object):
    """ RCI protocol message queue for incomming data.

    Takes incomming raw RCI responses, outputs full messages only.
    Handles situations where an incomplete message is received.

    This class is NOT thread-safe.
    """
    RESPONSE_DELIMITER = '\x00'

    def __init__(self):
        self._messages = []
        self._last_incomplete_message = ''

    @property
    def messages(self):
        """ Return all currently queued messages without their delimiters.

        Makes sure that no one is modifying the internal buffer.
        """
        return list(self._messages)

    @property
    def message_ready(self):
        """ Return True if a full response is ready and can be popped. """
        return len(self._messages) > 0

    def put(self, data):
        """ Find message(s) in data, put complete ones into queue.

        Completeness is evalueated based on whether a substring ends with
        RESPONSE_DELIMITER.

        If an incomplete message is found, it will be stored, and used as a
        prefix to the next portion of given data.
        """
        data = self._last_incomplete_message + data

        new_messages = data.split(self.RESPONSE_DELIMITER)

        self._last_incomplete_message = new_messages.pop()
        self._messages.extend(new_messages)

    def get(self):
        """ Get oldest complete message from the queue.

        Raises RCIQueueError if no complete messages are present.
        """
        if not self.message_ready:
            raise RCIQueueError("no message ready.")
        return self._messages.pop(0)

    def get_available(self):
        available = self._messages
        self._messages = []
        return available


class RCIQueueError(Exception):
    """ Class for exceptions related to RCI queues """
